esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We accept any caller-provided amount and will attempt one play call with it.
    // The function is payable so the test harness can fund this contract before calling.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // Ensure this test contract has enough balance to send the amount to c
        require(address(this).balance >= amount);
        // Read observable values before the state-changing call
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balanceCBefore = address(c).balance;

        bool reverted;
        // call play with provided amount as value; capture whether it reverted
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read observables after the call
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balanceCAfter = address(c).balance;

        // General rule:
        // - bank address is immutable (constructor set) and must not change
        // - if the call reverted, then nothing in c changed (pot and balance unchanged)
        // - if the call succeeded and amount equals TICKET_AMOUNT (10), then either:
        //     * pot increases by amount (caller did not win and no payout) OR
        //     * pot becomes zero (caller won and pot was paid out minus fee)
        // We express the rule without referring to private constants by comparing observed values.
        assert(
            // bank never changes
            bankBefore == bankAfter
            // if reverted: pot and balance unchanged
            && (reverted ? (potBefore == potAfter && balanceCBefore == balanceCAfter)
                : (
                    // call succeeded: either pot increased by exactly amount,
                    // or pot became zero and contract balance decreased accordingly
                    (
                        // pot increased by amount and contract balance increased by amount
                        potAfter == potBefore + amount && balanceCAfter == balanceCBefore + amount
                    )
                    ||
                    (
                        // pot reset to zero (winner case): potAfter == 0
                        // and contract balance decreased by (potBefore + amount - fee)
                        // We cannot read fee or transfers directly, but potAfter==0 captures reset
                        potAfter == 0
                    )
                )
            )
        );
    }

    // Allow contract to receive Ether for funding test calls
    receive() external payable {}
}

