// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address bankBefore;
        try c.bank() returns (address __r) { bankBefore = __r; } catch { return; }
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint balanceCBefore = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address bankAfter;
        try c.bank() returns (address __r) { bankAfter = __r; } catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint balanceCAfter = address(c).balance;
        assertTrue(bankBefore == bankAfter
            // if reverted: pot and balance unchanged
            && (reverted ? (potBefore == potAfter && balanceCBefore == balanceCAfter)
                : (
                    // call succeeded: either pot increased by exactly amount,
                    // or pot became zero and contract balance decreased accordingly
                    (
                        // pot increased by amount and contract balance increased by amount
                        potAfter == potBefore + amount && balanceCAfter == balanceCBefore + amount
                    )
                    ||
                    (
                        // pot reset to zero (winner case): potAfter == 0
                        // and contract balance decreased by (potBefore + amount - fee)
                        // We cannot read fee or transfers directly, but potAfter==0 captures reset
                        potAfter == 0
                    )
                )
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
